/**
 * Builds the published OpenAPI 3.1 document for the admin viewer API
 * (docs/viewer-api.openapi.yml) from the zod schemas and a route table.
 * Generated by `npm run build:viewer-schemas`; never edit the YAML by hand.
 */
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { stringify } from "yaml";
import { VIEWER_SCHEMAS } from "./api-schema.js";
import { viewerJsonSchema } from "./api-schema.js";
import { DEFAULT_GRAPH_LIMIT, MAX_GRAPH_LIMIT, SSE_HEARTBEAT_MS } from "./limits.js";

export const OPENAPI_PATH = join(dirname(fileURLToPath(import.meta.url)), "../../docs/viewer-api.openapi.yml");

type Json = Record<string, unknown>;

export interface ViewerRoute {
  path: string;
  operationId: string;
  summary: string;
  description: string;
  parameters?: readonly Json[];
  responses: Readonly<Record<string, Json>>;
}

const AUTH_NOTE = "Requires a bearer token with the `admin:view` scope, held by a caller with the admin role.";
const ref = (name: string): Json => ({ $ref: `#/components/schemas/${name}` });
const errorBody = (codes: string, description: string): Json => {
  const list = codes.split(", ");
  return {
    description,
    content: {
      "application/json": {
        schema: { allOf: [ref("ViewerError"), { properties: { error: { enum: list } } }] },
      },
    },
    "x-error-codes": list,
  };
};
const wwwAuthenticate: Json = { "WWW-Authenticate": { $ref: "#/components/headers/WWWAuthenticate" } };

export const VIEWER_ROUTES: readonly ViewerRoute[] = [
  {
    path: "/admin/api/graph",
    operationId: "getGraph",
    summary: "Graph snapshot",
    description: "Agents, runs, coding-run services and outcomes for a time window, as a graph.",
    parameters: [
      {
        name: "since",
        in: "query",
        required: false,
        description: "Window start: `15m`, `1h`, `6h`, `24h`, `7d`, or an ISO-8601 timestamp. Default `1h`.",
        schema: { type: "string", default: "1h" },
      },
      {
        name: "limit",
        in: "query",
        required: false,
        description: `Maximum number of runs, 1 to ${MAX_GRAPH_LIMIT}. Default ${DEFAULT_GRAPH_LIMIT}.`,
        schema: { type: "integer", minimum: 1, maximum: MAX_GRAPH_LIMIT, default: DEFAULT_GRAPH_LIMIT },
      },
    ],
    responses: {
      "200": {
        description: "The graph snapshot.",
        content: { "application/json": { schema: ref("graph-snapshot") } },
      },
      "400": errorBody("invalid_since, invalid_limit", "A query parameter is invalid."),
    },
  },
  {
    path: "/admin/api/runs/{id}",
    operationId: "getRun",
    summary: "Run detail",
    description: "Full detail for one run, including final text.",
    parameters: [{ name: "id", in: "path", required: true, description: "Run id.", schema: { type: "string" } }],
    responses: {
      "200": { description: "The run.", content: { "application/json": { schema: ref("run-detail") } } },
      "404": errorBody("not_found", "No run with that id."),
    },
  },
  {
    path: "/admin/api/infra",
    operationId: "getInfra",
    summary: "Infrastructure info",
    description: "Where and how this wardby deployment runs its workloads.",
    responses: {
      "200": { description: "Infrastructure info.", content: { "application/json": { schema: ref("infra-info") } } },
    },
  },
  {
    path: "/admin/api/events",
    operationId: "getEvents",
    summary: "Live event stream",
    description: [
      "A Server-Sent Events stream (`text/event-stream`) of live changes. Frames:",
      "",
      "- `retry: 3000`: suggested client reconnect delay in milliseconds.",
      '- `event: hello`: sent first. Data is `{"connected": <bool>}`, whether the server\'s live-event connection is up.',
      "- `event: run`, `event: service`, `event: outcome`: a run, coding-run service, or outcome changed. Each carries an `id:` line. Payloads match the `viewer-event` schema (see `x-event-schema`).",
      '- `event: status`: the server\'s live-event connection changed. Data is `{"connected": <bool>}`.',
      "- `event: resync`: the live-event connection is up (again). Events may have been missed: refetch the graph.",
      `- \`: ping\`: comment sent every ${SSE_HEARTBEAT_MS / 1000} seconds to keep the connection open.`,
      "",
      "There is no replay. Open the event stream first, then load `/admin/api/graph` and apply events on top of it. Refetch the graph on every `resync` and after every reconnect rather than trying to resume.",
    ].join("\n"),
    responses: {
      "200": {
        description: "The event stream.",
        content: { "text/event-stream": { schema: { type: "string" } } },
        "x-event-schema": ref("viewer-event"),
      },
    },
  },
];

function componentSchemas(): Json {
  const schemas: Json = {};
  for (const [name, schema] of Object.entries(VIEWER_SCHEMAS)) {
    schemas[name] = viewerJsonSchema(schema);
  }
  schemas.ViewerError = {
    type: "object",
    required: ["error"],
    properties: { error: { type: "string" } },
    additionalProperties: false,
  };
  schemas.ViewerInternalError = {
    type: "object",
    required: ["error", "id"],
    properties: { error: { type: "string", enum: ["internal_error"] }, id: { type: "string" } },
    additionalProperties: false,
  };
  return schemas;
}

function operation(route: ViewerRoute): Json {
  return {
    operationId: route.operationId,
    summary: route.summary,
    description: `${route.description}\n\n${AUTH_NOTE}`,
    security: [{ bearer: [] }],
    ...(route.parameters ? { parameters: route.parameters } : {}),
    responses: {
      ...route.responses,
      "401": { ...errorBody("invalid_token", "No valid bearer token."), headers: wwwAuthenticate },
      "403": {
        ...errorBody(
          "invalid_token",
          "Token lacks the `admin:view` scope (the `WWW-Authenticate` header is present), or the caller lacks the admin role (no `WWW-Authenticate` header).",
        ),
        headers: wwwAuthenticate,
      },
      "405": {
        ...errorBody("method_not_allowed", "Only GET is allowed."),
        headers: { Allow: { description: "Allowed methods: GET.", schema: { type: "string", enum: ["GET"] } } },
      },
      default: {
        description: "Unexpected server error (HTTP 500). `id` identifies the failure in the server log.",
        content: { "application/json": { schema: ref("ViewerInternalError") } },
      },
    },
  };
}

export function buildViewerOpenApi(version: string): Json {
  const paths: Json = {};
  for (const route of VIEWER_ROUTES) paths[route.path] = { get: operation(route) };
  return {
    openapi: "3.1.0",
    info: {
      title: "wardby admin viewer API",
      version,
      description:
        "Read-only admin API behind the wardby viewer: graph, run detail, infrastructure info and a live event stream. Response objects may gain new fields in later releases; clients should ignore unknown fields. See docs/viewer-api.md for the prose contract.",
    },
    servers: [{ url: "https://{host}", variables: { host: { default: "wardby.example.com" } } }],
    paths,
    components: {
      securitySchemes: { bearer: { type: "http", scheme: "bearer" } },
      headers: { WWWAuthenticate: { description: "Bearer challenge.", schema: { type: "string" } } },
      schemas: componentSchemas(),
    },
  };
}

export const HEADER =
  "# Generated by npm run build:viewer-schemas from src/viewer/api-schema.ts and src/viewer/openapi.ts. Do not edit.";

export function renderViewerOpenApi(version: string): string {
  return `${HEADER}\n${stringify(buildViewerOpenApi(version), { lineWidth: 0, aliasDuplicateObjects: false })}`;
}
